// Narration timing on the single full-film timeline (data/vo.ts is generated by tools/assemble_natural.py).
import { VO, VO_TOTAL } from "./data/vo";
import { FPS } from "./theme";

export { VO, VO_TOTAL };
export const FULL_FRAMES = Math.ceil(VO_TOTAL * FPS);

const CJK = "\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uac00-\ud7af\uf900-\ufaff";
const norm = (s: string) => s.toLowerCase().replace(new RegExp(`[^a-z0-9${CJK}]`, "g"), "");
// Chinese narration is tokenized per character (tools/textutil.py): no spaces next to CJK characters or full-width punctuation.
const WIDE = new RegExp(`[${CJK}\u3000-\u303f\uff00-\uffef]`);
const isWide = (ch: string | undefined) => !!ch && WIDE.test(ch);
const IDEO = new RegExp(`[${CJK}]`);
const latin = (ch: string | undefined) => !!ch && /[A-Za-z0-9]/.test(ch);
// space rule (same as tools/textutil.py join): Latin-Latin yes; CJK next to a Latin word or number yes (XYZ 达到 48.2);
// nothing next to full-width punctuation or between two CJK characters
export const sep = (prev: string, next: string) => {
  const x = prev[prev.length - 1], y = next[0];
  if (!isWide(x) && !isWide(y)) return " ";
  if ((IDEO.test(x || "") && latin(y)) || (IDEO.test(y || "") && latin(x))) return " ";
  return "";
};
export const joinWords = (ws: string[]) => ws.reduce((s, w, i) => (i ? s + sep(ws[i - 1], w) + w : w), "");
const width = (s: string) => [...s].reduce((n, c) => n + (isWide(c) ? 2.2 : 1), 0);

// Absolute time (s) where `phrase` starts (or ends) inside line `id`. Throws on a typo instead of silently falling back.
export const at = (id: string, phrase?: string, end = false): number => {
  const l = VO[id];
  if (!l) throw new Error(`no narration line ${id}`);
  if (!phrase) return end ? l.end : l.start;
  const toks = l.words.map((w) => norm(w[0]));
  const p = norm(phrase);
  const idx = toks.join("").indexOf(p);
  if (idx < 0) throw new Error(`"${phrase}" not found in ${id}: ${l.text}`);
  const target = end ? idx + p.length - 1 : idx;
  let acc = 0;
  for (let i = 0; i < toks.length; i++) {
    if (target < acc + toks[i].length) return end ? l.words[i][2] : l.words[i][1];
    acc += toks[i].length;
  }
  return end ? l.end : l.start;
};

// Captions: split at sentence ends first, then syntax-aware balanced chunking only for long sentences.
const MAX_SINGLE = 78;
const MAX_TARGET = 64;
const NO_BREAK_AFTER = new Set([
  "a", "an", "the", "of", "to", "by", "for", "on", "in", "at", "with", "from", "between",
  "into", "under", "across", "against", "and", "or", "that", "its", "their", "our", "each",
  "every", "more", "than", "one", "single", "does", "is", "are", "was", "can", "may",
  "all", "start", "tell", "produced",
]);
const NO_BREAK_BEFORE = new Set(["of", "to"]);
const CLAUSE_STARTERS = new Set([
  "and", "while", "so", "yet", "but", "against", "once", "where", "after", "without", "under", "with", "that",
]);

export type Seg = {
  id: string;
  text: string;
  start: number;
  end: number;
  words: Array<[string, number, number]>;
  prevEnd: number;
  nextStart: number;
};

type Word = [string, number, number];
const splitSentence = (words: Word[]): Word[][] => {
  const fullLen = width(joinWords(words.map((w) => w[0])));
  if (fullLen <= MAX_SINGLE || words.length < 6) return [words];
  const k = Math.max(2, Math.ceil(fullLen / MAX_TARGET));
  const target = fullLen / k;
  const pref = [0];
  for (let i = 0; i < words.length; i++) pref.push(pref[i] + width(words[i][0]) + (i > 0 ? sep(words[i - 1][0], words[i][0]).length : 0));
  const chunkLen = (a: number, b: number) => pref[b] - pref[a] - (a > 0 ? sep(words[a - 1][0], words[a][0]).length : 0);

  const splitPenalty = (i: number) => {
    const w = words[i - 1][0];
    const nxt = words[i][0];
    const wCore = w.toLowerCase().replace(/[^a-z-]/g, "");
    const nxtCore = nxt.toLowerCase().replace(/[^a-z]/g, "");
    let p = 0;
    if (/[:;：；]$/.test(w)) p -= 5.0;
    else if (/[,，、]$/.test(w)) p -= 3.8;
    if (NO_BREAK_AFTER.has(wCore) || NO_BREAK_BEFORE.has(nxtCore)) p += 8.0;
    if (CLAUSE_STARTERS.has(nxtCore)) p -= 1.8;
    return p;
  };

  if (k === 2) {
    let bestI = 3, bestCost = Infinity;
    for (let i = 3; i <= words.length - 3; i++) {
      const l1 = chunkLen(0, i), l2 = chunkLen(i, words.length);
      const cost = ((l1 - target) / 14) ** 2 + ((l2 - target) / 14) ** 2 + (l1 > 80 ? 50 : 0) + (l2 > 80 ? 50 : 0) + splitPenalty(i);
      if (cost < bestCost) { bestCost = cost; bestI = i; }
    }
    return [words.slice(0, bestI), words.slice(bestI)];
  }

  let bestPair: [number, number] = [3, Math.max(6, words.length - 3)], bestCost = Infinity;
  for (let i = 3; i <= words.length - 6; i++) {
    for (let j = i + 3; j <= words.length - 3; j++) {
      const l1 = chunkLen(0, i), l2 = chunkLen(i, j), l3 = chunkLen(j, words.length);
      const cost =
        ((l1 - target) / 14) ** 2 + ((l2 - target) / 14) ** 2 + ((l3 - target) / 14) ** 2 +
        (l1 > 80 ? 50 : 0) + (l2 > 80 ? 50 : 0) + (l3 > 80 ? 50 : 0) +
        splitPenalty(i) + splitPenalty(j);
      if (cost < bestCost) { bestCost = cost; bestPair = [i, j]; }
    }
  }
  return [words.slice(0, bestPair[0]), words.slice(bestPair[0], bestPair[1]), words.slice(bestPair[1])];
};

const splitLine = (words: Word[]): Word[][] => {
  const sentences: Word[][] = [];
  let cur: Word[] = [];
  for (const w of words) {
    cur.push(w);
    if (/[.?!。？！]$/.test(w[0])) { sentences.push(cur); cur = []; }
  }
  if (cur.length) sentences.push(cur);
  // Keep very short adjacent sentences paired if they fit comfortably on one line (e.g. "b3" / "r3")
  const out: Word[][] = [];
  for (const s of sentences) {
    for (const chunk of splitSentence(s)) out.push(chunk);
  }
  return out;
};

const segs: Seg[] = [];
for (const [id, l] of Object.entries(VO)) {
  for (const chunk of splitLine(l.words)) {
    segs.push({
      id,
      text: joinWords(chunk.map((w) => w[0])),
      start: chunk[0][1],
      end: chunk[chunk.length - 1][2],
      words: chunk,
      prevEnd: -1e9,
      nextStart: 1e9,
    });
  }
}
for (let i = 0; i < segs.length; i++) {
  segs[i].prevEnd = i > 0 ? segs[i - 1].end : -1e9;
  segs[i].nextStart = i + 1 < segs.length ? segs[i + 1].start : 1e9;
}

export const SEGS = segs;
export const captionAt = (t: number): Seg | undefined =>
  SEGS.find((s) => {
    const hi = s.nextStart < 1e8 ? Math.min(s.end + 0.25, (s.end + s.nextStart) / 2) : s.end + 0.25;
    return t >= s.start - 0.05 && t < hi;
  });
